"""A01C: player/request continuation and ALL resolution, separated from lexer flags."""
import sys,json
from pathlib import Path
sys.dont_write_bytecode=True
p=Path(__file__).resolve().parents[2];sys.path.insert(0,str(p/'skoolkit-10.1'))
from skoolkit.traceutils import disassemble
from skoolkit.z80 import Assembler
m=bytes(0x5d80)+(p/'sherlock-analisi/block-10.bin').read_bytes();asm=Assembler()
regions=[(0xA01D,0xA01F,'data','Flag persistenti del modello lessicale selezionato'),(0xA2B1,0xA2E4,'code','Selezione modello e decomposizione dei quattro nibble'),(0xA2E4,0xA31A,'code','Gating dell’annuncio: anche fuori scena rilegge il modello'),(0xA31A,0xA35D,'code','Annuncio: ricarica i flag prima del testo e conserva i residui'),(0xA37D,0xA419,'code','Composizione degli ordini: aggiorna i flag del modello stampato'),(0xB1DD,0xB213,'code','Resolver: classi e presenza degli argomenti dai flag'),(0xB405,0xB468,'code','Modello lessicale e ordine fisico dei complementi'),(0xC493,0xC4D1,'code','Classi zero, locazione, letterale ed entità dal modello'),(0xC4D1,0xC55A,'code','Dispatch delle azioni: modello dati e argomenti mancanti'),(0xCA76,0xCA7F,'code','Annuncio del movimento interno: lookup anche fuori scena'),(0xE345,0xE34F,'code','Pagamento interno: seleziona PAY per il successivo annuncio')]
notes={0xE34B:'Dopo il controllo di fondi, imposta azione25hex=37dec PAY. Il successivo annuncio CA76/A323 aggiorna i flag anche fuori scena; non resta il precedente modello CLOSE di un altro attore.',0xCA76:'Il movimento interno seleziona la direzione e passa ad A2E4 anche se fuori scena. La visibilità regola il testo, non elimina il successivo decoder dei flag.',0xA30C:'Se attore non percepibile e modo annuncio1, A310 passa comunque ad A31A e al decoder A323. Non limitare la proprietà dei flag ai soli messaggi visibili.',0xA01D:'A01D flags=(modello[1]>>4)|(modello[3]&F0); A01E modi=(modello[5]>>4)|(modello[7]&F0). Sono due byte dati persistenti: nessun reset per tick, errore lessicale o nuovo comando senza modello. Vecchio LOAD assente resta unknown.',0xA2B1:'Azione1..54:8259+8*(id-1). I byte sono dati lessicali, non istruzioni.',0xA2BD:'Un solo decoder per i quattro chiamanti B416,C4DF,A323,A38B. Prima scrive A01E, poi A01D. I nibble bassi dei riferimenti lessicali non entrano nei flag.',0xA2CD:'Writer di A01E: combina il nibble alto del byte5 come nibble basso, e quello del byte7 come alto.',0xA2E0:'Writer di A01D: combina i nibble alti dei byte1 e3. Nessun salvataggio/ripristino del precedente modello.',0xA323:'Anche gli annunci leggono il modello; questo writer non è limitato al comando inserito dal giocatore.',0xA329:'Bit4 di A01D sopprime il normale annuncio. Il decoder è già passato e quindi i flag restano aggiornati anche se il testo viene saltato.',0xA38B:'Il testo composto di un ordine aggiorna A01D/E con il modello dell’azione citata, non necessariamente SAY/TELL esterno.',0xB416:'Dopo il riconoscimento del modello, prima di classi e ordine dei complementi. Errori che non raggiungono il riconoscimento conservano i flag precedenti.',0xB440:'Bit5 del primo flag governa l’ordine dei gruppi fisici. Il XOR20 modifica soltanto A nel registro, non A01D.',0xC497:'Bit3 richiede il primo argomento. Se assente, classe0.',0xC49D:'Bit7 indica prima classe4 (locazione). Altrimenti modo A01E&0C=0C dà classe5, gli altri classe7.',0xC4B6:'Bit2 richiede il secondo argomento; bit6 sceglie locazione. A01E&03=03 sceglie letterale, altrimenti entità.',0xC4DF:'Ogni azione normale carica il proprio modello prima del preflight. Le regole interne >=128 saltano direttamente a C583 e non fanno questo store.',0xC4EC:'Maschera0C: presenza dei due argomenti. Non equivale alle classi effettive delle regole DOMAIN, che possono sovrascrivere A00F/A010 senza cambiare A01D/E.',0xC54E:'Bit1 consente il secondo argomento non specificato nella ricerca delle azioni.'}
lines=['; Dossier offline: istruzioni riassemblate e dati tipizzati; nessuna CPU nel runtime.'];count=total=0
for a,b,kind,label in regions:
 lines+=['',f'    ORG ${a:04X}',f'; {kind.upper()}: {label}'];at=a
 while at<b:
  if kind=='data':n=b-at;op='DEFB '+','.join(f'${v:02X}'for v in m[at:b])
  else:op,n=disassemble(m,at);count+=1
  assert at+n<=b,(hex(at),op);assert bytes(asm.assemble(op,at))==m[at:at+n]
  lines.append(f'    {op:<37} ; ${at:04X} {m[at:at+n].hex(" ")}'+(' | '+notes[at]if at in notes else''));at+=n;total+=n
root=p/'sherlock-js/results/model-flags';root.mkdir(exist_ok=True)
(root/'model-flags.asm').write_text('\n'.join(lines)+'\n')
(root/'listing-verification.json').write_text(json.dumps(dict(roundtrip_equal=True,instructions=count,bytes_roundtripped=total,regions=[dict(start=f'{a:04X}',end_exclusive=f'{b:04X}',kind=k,label=l,atlas_priority=125 if k=='data' else 96)for a,b,k,l in regions]),indent=2)+'\n');print(count,total)
